// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 oracleVersion) public {
        // atVersion should not revert and should return a valid oracle version with finite price
        // The reference implementation uses the oracle to get the price; if oracle is null, the call reverts
        // So we check that atVersion always succeeds (doesn't revert)
        // We use try/catch to capture revert and assert reverted flag based on oracle being null or not
        // Since we can't directly check oracle() return, we rely on the fact that when oracle is null,
        // atVersion will revert (since it tries to call atVersion on address(0))
        // So the general rule: for all inputs, atVersion should not revert

        // Bound version to reasonable range (0 to 1e6 should cover all practical versions)
        oracleVersion = bound(oracleVersion, 0, 1_000_000);

        bool reverted;
        try c.atVersion(oracleVersion) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assertTrue(!reverted, "atVersion should never revert");
    }
}

