pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 version) public {
        // Bound version to a reasonable range to avoid out-of-bounds errors
        version = bound(version, 0, 1000);

        // The rule: the oracle address from atVersion must match the oracle address from oracle()
        // We call atVersion(version) and compare the oracle address (obtained by reading the returned struct)
        // However, the struct OracleVersion has fields: version, timestamp, price. The oracle address is not in the struct.
        // The intended check is that the oracle() view returns the same address used internally.
        // Since the bug changes oracle() to return address(0), we can check that oracle() is not zero.
        // But the rule must hold on reference and break on mutant. The mutant returns zero, so we assert oracle() != address(0).
        // This is a general rule satisfied by the reference and broken by the mutant.
        assertTrue(address(c.oracle()) != address(0));
    }
}

