pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 version) public {
        // Chain: call atVersion(version) then compare with currentVersion
        // The reference: currentVersion() returns the latest; atVersion(version) returns that specific version.
        // For the bug: currentVersion() always returns atVersion(0), which is the first version, regardless of the actual oracle state.
        // We can test the property: atVersion(version) should equal atVersion(version) — trivial. But the difference is that currentVersion() should equal the latest, not the first.
        // Since we cannot directly query the oracle's true latest, we simulate by calling currentVersion() and comparing with atVersion(latestVersion) to ensure consistency.
        // For any version, atVersion(version) is deterministic. The bug is that currentVersion() returns atVersion(0) always.
        // To catch this, we call currentVersion() and atVersion(version) for two different versions and check if they are equal when they shouldn't be.
        // Simpler: assume we have a way to advance oracle versions. Without that, we rely on the fact that buggy currentVersion returns atVersion(0) for any state.
        // Thus, for two different versions, if atVersion(v1) != atVersion(v2), then currentVersion() cannot equal both.
        // We'll pick two versions: 0 and some nonzero (like 1). If buggy, currentVersion() == atVersion(0) always, so it will equal atVersion(0) but not atVersion(1) (if they differ).
        // But we need a general rule. We'll assert: currentVersion() equals atVersion(latestVersion) where latestVersion = c.latestVersion().
        // This holds for P (since currentVersion returns latest) but fails for M (since M returns atVersion(0) which may not be latest).
        vm.assume(version <= 100); // avoid overflow in view
        // No setup needed; just read and compare.
        uint256 latestVersion = c.latestVersion();
        (uint256 v_cur, , ) = c.currentVersion();
        (uint256 v_at, , ) = c.atVersion(latestVersion);
        assertTrue(v_cur == v_at, "currentVersion should equal atVersion(latestVersion)");
    }
}

