pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 oracleVersion) public {
        vm.assume(oracleVersion > 0 && oracleVersion < type(uint256).max);
        // Get price at a historical version
        (uint256 vAt, uint256 tAt, int256 pAt) = c.atVersion(oracleVersion);
        // Sync to get current version
        (uint256 vCur, uint256 tCur, int256 pCur) = c.sync();
        // The current version must be at least the queried version
        assertTrue(vCur >= vAt);
    }
}

