pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 oracleVersion) public {
        // We need to initialize the contract first. We'll call a function that triggers a settle to set up oracle.
        // Since atVersion reads from the controller's oracle, we can check consistency.
        // If atVersion reverts, that's fine, we just ensure it doesn't on the reference.
        // For this test, we assume the contract is initialized. We'll use vm.assume to skip versions that cause revert on reference.
        // Bound oracleVersion to a reasonable range to avoid overflow issues
        vm.assume(oracleVersion <= type(uint128).max);

        // Get the controller address from the contract
        address controllerAddr = address(c.controller());

        // Try to call atVersion and see if it reverts
        bool reverted = false;
        try c.atVersion(oracleVersion) {
            reverted = false;
