import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller) public {
        // Ensure caller is not zero (avoid trivial cases)
        vm.assume(caller != address(0));

        // Get the controller address from the contract via atVersion (this triggers a view call)
        // We need to deploy a minimal controller-like address to simulate
        // Instead, we directly check the controller() function behavior
        // The rule: controller() should NOT return msg.sender of the call

        vm.prank(caller);
        IController returnedController = c.controller();
        address controllerAddr = address(returnedController);

        // In the reference version, controller() returns the stored controller address
        // which was set during initialization (passed as msg.sender to initialize)
        // For a freshly deployed contract with no initialize call, controller() returns address(0) from storage
        // In the buggy version, it returns the caller address
        // So the general rule is: controller() should NOT return the caller
        assertTrue(controllerAddr != caller, "controller() should not return msg.sender");
    }
}

